"""configloader — implement parse_config and get per README.md."""


def _coerce(value):
    """Coerce a raw string value to bool/int/float, or keep it a string."""
    if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
        return value[1:-1]
    lowered = value.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value


def parse_config(text):
    """Parse .ini-style config text into {section: {key: value}}."""
    config = {}
    section = ""
    config[section] = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue
        if "=" not in line:
            continue
        key, _, value = line.partition("=")
        config[section][key.strip()] = _coerce(value.strip())
    return config


def get(config, dotted, default=None):
    """Look up "section.key" in a parsed config; return default if absent."""
    section, _, key = dotted.partition(".")
    if not key:
        section, key = "", section
    return config.get(section, {}).get(key, default)

